"use client";

import { FieldStudy, type FieldStudyProps } from "./studies/field-study";

export type DotMigrationProps = Omit<FieldStudyProps, "variant">;

export function DotMigration(props: DotMigrationProps) {
  return <FieldStudy variant="dot-migration" {...props} />;
}

"use client";

import { useId, useRef } from "react";
import { motion, useInView, useReducedMotion } from "motion/react";
import { getFieldStudyAddition, isAddedFieldStudyVariant } from "./field-study-additions";

export const fieldStudyVariants = [
  "orbit-field", "contour-paper", "scan-matrix", "ripple-grid", "spark-cloud", "ribbon-vector",
  "chromatic-fan", "star-chart", "line-topography", "signal-horizon", "color-loom", "shard-field",
  "ribbon-mesh", "wave-grid", "radial-loom", "dot-migration", "moire-window", "orbit-lattice",
  "beacon-sweep", "ripple-basin", "wireframe-hills", "particle-drift", "raster-rain", "lens-rings",
  "crosshair-field", "folded-grid", "petal-array", "signal-constellation", "soft-gridlight", "contour-drift",
  "angular-flow", "orbit-clock",
] as const;
export type FieldStudyVariant = (typeof fieldStudyVariants)[number];

export interface FieldStudyProps {
  label?: string;
  accent?: string;
  intensity?: number;
  pace?: number;
  variant: FieldStudyVariant;
}

export function FieldStudy({ accent = "var(--electric, #5038ff)", intensity = 12, pace = 1, variant }: FieldStudyProps) {
  const rootRef = useRef<SVGSVGElement>(null);
  const additionRef = useRef<HTMLDivElement>(null);
  const instanceId = useId().replaceAll(":", "");
  const isInView = useInView(rootRef, { amount: 0.1 });
  const isAdditionInView = useInView(additionRef, { amount: 0.1 });
  const reduceMotion = useReducedMotion() ?? false;
  const animate = !reduceMotion && (isInView || isAdditionInView);
  const duration = Math.max(2.5, 9 / Math.max(0.25, pace));
  const strength = Math.max(0.15, Math.min(1, intensity / 16));
  const lines = Array.from({ length: 9 }, (_, index) => index);
  const rootStyle = { width: "100%", height: 180, display: "block", position: "relative" as const, opacity: strength };

  if (isAddedFieldStudyVariant(variant)) {
    return <div ref={additionRef} style={{ width: "100%", height: 180, position: "relative" }}>{getFieldStudyAddition({ accent, animate, duration, instanceId, rootStyle, variant })}</div>;
  }

  if (variant === "orbit-field" || variant === "star-chart" || variant === "orbit-lattice" || variant === "orbit-clock") {
    if (variant === "orbit-clock") {
      return <svg ref={rootRef} aria-hidden="true" viewBox="0 0 320 160" preserveAspectRatio="xMidYMid meet" style={rootStyle}><circle cx="160" cy="80" r="58" fill="none" stroke={accent} strokeOpacity=".35" /><circle cx="160" cy="80" r="3" fill={accent} />{[0, 1, 2].map((index) => <motion.line key={index} x1="160" y1="80" x2="160" y2={index === 0 ? 28 : index === 1 ? 40 : 54} stroke={accent} strokeWidth={index === 0 ? 2 : 1} style={{ transformOrigin: "160px 80px" }} animate={animate ? { rotate: 360 } : undefined} transition={{ duration: duration * (index + 1), repeat: Infinity, ease: "linear" }} />)}<motion.circle cx="160" cy="80" r="72" fill="none" stroke={accent} strokeDasharray="2 6" animate={animate ? { rotate: -360 } : undefined} transition={{ duration: duration * 2, repeat: Infinity, ease: "linear" }} style={{ transformOrigin: "160px 80px" }} /></svg>;
    }
    return (
      <svg ref={rootRef} aria-hidden="true" viewBox="0 0 320 160" preserveAspectRatio="none" style={rootStyle}>
        <g fill="none" stroke={accent} strokeWidth="1">
          {lines.slice(0, 5).map((index) => (
            <motion.ellipse key={index} cx="160" cy="80" rx={24 + index * 17} ry={10 + index * 8}
              animate={animate ? { rotate: index % 2 ? 360 : -360 } : undefined}
              transition={{ duration: duration + index, repeat: Infinity, ease: "linear" }}
              style={{ transformOrigin: "160px 80px" }} />
          ))}
        </g>
        {lines.map((index) => {
          const angle = (index / 9) * Math.PI * 2;
          const cx = 160 + Math.cos(angle) * (38 + index * 11);
          const cy = 80 + Math.sin(angle) * (15 + index * 7);
          return <motion.circle key={index} cx={cx} cy={cy} r={2 + index % 3} fill={accent}
            animate={animate ? { opacity: [0.3, 1, 0.3], scale: [0.8, 1.4, 0.8] } : undefined}
            transition={{ duration: duration / 2, repeat: Infinity, delay: index * 0.13 }} />;
        })}
      </svg>
    );
  }

  if (variant === "scan-matrix" || variant === "signal-horizon") {
    return (
      <svg ref={rootRef} aria-hidden="true" viewBox="0 0 320 160" preserveAspectRatio="none" style={rootStyle}>
        <defs><pattern id={`scan-${variant}`} width="12" height="12" patternUnits="userSpaceOnUse"><path d="M0 11.5H12" stroke={accent} strokeOpacity=".32" /></pattern></defs>
        <rect width="320" height="160" fill={`url(#scan-${variant})`} />
        <motion.rect width="320" height="2" fill={accent}
          animate={animate ? { y: [0, 158, 0], opacity: [0, 0.9, 0] } : undefined}
          transition={{ duration, repeat: Infinity, ease: "linear" }} />
        <path d="M0 114 Q40 82 80 114 T160 114 T240 114 T320 114" fill="none" stroke={accent} strokeWidth="2" />
      </svg>
    );
  }

  if (variant === "shard-field") {
    return (
      <svg ref={rootRef} aria-hidden="true" viewBox="0 0 320 160" preserveAspectRatio="xMidYMid slice" style={rootStyle}>
        {lines.map((index) => <motion.polygon key={index}
          points={`${index * 40},0 ${index * 40 + 32},${30 + index * 9} ${index * 40 + 8},160`}
          fill="none" stroke={accent} strokeWidth="1.5"
          animate={animate ? { x: [0, 10, 0], opacity: [0.24, 0.9, 0.24] } : undefined}
          transition={{ duration: duration + index / 3, repeat: Infinity, delay: index * 0.12 }} />)}
      </svg>
    );
  }

  if (variant === "ribbon-vector" || variant === "color-loom" || variant === "line-topography") {
    return (
      <svg ref={rootRef} aria-hidden="true" viewBox="0 0 320 160" preserveAspectRatio="none" style={rootStyle}>
        {lines.map((index) => <motion.path key={index}
          d={variant === "line-topography"
            ? `M-10 ${15 + index * 17} C70 ${-10 + index * 20}, 90 ${170 - index * 8}, 170 ${75 + index * 4} S260 ${index * 16}, 330 ${30 + index * 13}`
            : `M-10 ${20 + index * 16} C80 ${130 - index * 10}, 140 ${-20 + index * 13}, 330 ${20 + index * 14}`}
          fill="none" stroke={accent} strokeWidth={index % 3 === 0 ? 1.5 : 0.75}
          strokeOpacity={0.3 + (index % 4) * 0.14}
          strokeDasharray={variant === "ribbon-vector" ? "5 8" : undefined}
          animate={animate ? { pathLength: [0.35, 1, 0.35], x: [-8, 8, -8] } : undefined}
          transition={{ duration: duration + index / 2, repeat: Infinity, ease: "easeInOut", delay: index * 0.11 }} />)}
      </svg>
    );
  }

  if (variant === "chromatic-fan") {
    return (
      <svg ref={rootRef} aria-hidden="true" viewBox="0 0 320 160" preserveAspectRatio="none" style={rootStyle}>
        {lines.map((index) => <motion.path key={index} d={`M160 190 L${-40 + index * 50} -20`}
          stroke={accent} strokeWidth="12" strokeOpacity=".12"
          animate={animate ? { rotate: [index % 2 ? -9 : 9, index % 2 ? 9 : -9] } : undefined}
          transition={{ duration: duration + index / 3, repeat: Infinity, repeatType: "mirror", ease: "easeInOut" }}
          style={{ transformOrigin: "160px 80px" }} />)}
      </svg>
    );
  }

  return (
    <svg ref={rootRef} aria-hidden="true" viewBox="0 0 320 160" preserveAspectRatio="none" style={rootStyle}>
      {variant === "ripple-grid"
        ? lines.map((index) => <motion.circle key={index} cx={40 + (index % 5) * 60} cy={30 + Math.floor(index / 5) * 65} r="16" fill="none" stroke={accent} strokeWidth="1.5"
          animate={animate ? { r: [5, 28, 5], opacity: [0.8, 0.05, 0.8] } : undefined}
          transition={{ duration, repeat: Infinity, delay: index * 0.2 }} />)
        : lines.map((index) => <motion.circle key={index} cx={(index * 43) % 320} cy={(index * 67) % 160} r={2 + index % 3} fill={accent}
          animate={animate ? { cy: [20 + (index * 11) % 120, 140 - (index * 9) % 100, 20 + (index * 11) % 120], opacity: [0.2, 0.9, 0.2] } : undefined}
          transition={{ duration: duration + index / 3, repeat: Infinity, delay: index * 0.17 }} />)}
    </svg>
  );
}

"use client";

import type { CSSProperties } from "react";
import { motion } from "motion/react";

export type AddedFieldStudyVariant =
  | "ribbon-mesh" | "wave-grid" | "wireframe-hills" | "contour-drift" | "angular-flow"
  | "radial-loom" | "moire-window" | "petal-array"
  | "dot-migration" | "signal-constellation" | "particle-drift"
  | "beacon-sweep" | "ripple-basin" | "lens-rings"
  | "crosshair-field" | "raster-rain" | "folded-grid" | "soft-gridlight";

const addedFieldStudyVariants = new Set<string>([
  "ribbon-mesh", "wave-grid", "wireframe-hills", "contour-drift", "angular-flow",
  "radial-loom", "moire-window", "petal-array", "dot-migration", "signal-constellation",
  "particle-drift", "beacon-sweep", "ripple-basin", "lens-rings", "crosshair-field",
  "raster-rain", "folded-grid", "soft-gridlight",
]);

export function isAddedFieldStudyVariant(variant: string): variant is AddedFieldStudyVariant {
  return addedFieldStudyVariants.has(variant);
}

interface FieldStudyAdditionProps {
  accent: string;
  animate: boolean;
  duration: number;
  instanceId: string;
  rootStyle: CSSProperties;
  variant: AddedFieldStudyVariant;
}

export function getFieldStudyAddition({
  accent,
  animate,
  duration,
  instanceId,
  rootStyle,
  variant,
}: FieldStudyAdditionProps) {
  const lines = Array.from({ length: 9 }, (_, index) => index);

  if (["ribbon-mesh", "wave-grid", "wireframe-hills", "contour-drift", "angular-flow"].includes(variant)) {
    return (
      <svg aria-hidden="true" viewBox="0 0 320 160" preserveAspectRatio="none" style={rootStyle}>
        {lines.map((index) => {
          const y = 16 + index * 16;
          const path = variant === "wave-grid"
            ? `M-8 ${y} C38 ${y - 22}, 62 ${y + 22}, 108 ${y} S178 ${y - 22}, 224 ${y} S286 ${y + 22}, 328 ${y}`
            : variant === "ribbon-mesh"
              ? `M-8 ${index * 22 - 16} C90 ${index * 16 + 36}, 210 ${140 - index * 14}, 328 ${index * 20}`
              : variant === "wireframe-hills"
                ? `M-8 ${y + 15} Q48 ${y - 25 - index * 2} 102 ${y + 5} T210 ${y - 4} T328 ${y + 10}`
                : variant === "angular-flow"
                  ? `M-8 ${y} H${45 + index * 8} V${y + 15} H${155 + index * 4} V${y - 12} H328`
                  : `M-8 ${y} C72 ${y - 14}, 112 ${y + 18}, 164 ${y} S252 ${y - 18}, 328 ${y + 8}`;
          return (
            <motion.path
              key={index}
              d={path}
              fill="none"
              stroke={accent}
              strokeWidth={index % 3 === 0 ? 1.4 : 0.7}
              strokeOpacity={0.32 + (index % 4) * 0.12}
              animate={animate ? {
                x: [variant === "angular-flow" ? 0 : -5, variant === "angular-flow" ? 0 : 5, 0],
                y: variant === "contour-drift" ? [0, index % 2 ? -5 : 5, 0] : 0,
                pathLength: variant === "angular-flow" ? [0.7, 1, 0.7] : 1,
              } : undefined}
              transition={{ duration: duration + index / 3, repeat: Infinity, ease: "easeInOut", delay: index * 0.08 }}
            />
          );
        })}
      </svg>
    );
  }

  if (["radial-loom", "moire-window", "petal-array"].includes(variant)) {
    return (
      <svg aria-hidden="true" viewBox="0 0 320 160" preserveAspectRatio="none" style={rootStyle}>
        <g transform={variant === "moire-window" ? "translate(18 0)" : undefined}>
          {lines.map((index) => variant === "petal-array" ? (
            <motion.ellipse
              key={index}
              cx="160"
              cy="80"
              rx={10 + index * 5}
              ry={34}
              fill="none"
              stroke={accent}
              strokeOpacity={0.24 + (index % 4) * 0.13}
              transform={`rotate(${index * 20} 160 80)`}
              animate={animate ? { rotate: [index * 20, index * 20 + 360] } : undefined}
              transition={{ duration: duration * 2 + index, repeat: Infinity, ease: "linear" }}
              style={{ transformOrigin: "160px 80px" }}
            />
          ) : (
            <motion.path
              key={index}
              d={variant === "radial-loom"
                ? `M160 80 L${160 + Math.cos(index * Math.PI / 9) * 190} ${80 + Math.sin(index * Math.PI / 9) * 120}`
                : `M${-20 + index * 42} -10 C${65 + index * 16} 35, ${100 + index * 12} 125, ${340 - index * 32} 170`}
              fill="none"
              stroke={accent}
              strokeOpacity={0.22 + (index % 5) * 0.12}
              strokeWidth={variant === "moire-window" ? 1.2 : 0.9}
              animate={animate ? {
                rotate: variant === "radial-loom" ? [index % 2 ? -2 : 2, index % 2 ? 2 : -2] : 0,
                x: variant === "moire-window" ? [0, index % 2 ? -4 : 4, 0] : 0,
              } : undefined}
              transition={{ duration: duration + index / 2, repeat: Infinity, ease: "easeInOut" }}
              style={{ transformOrigin: "160px 80px" }}
            />
          ))}
        </g>
      </svg>
    );
  }

  if (["dot-migration", "signal-constellation", "particle-drift"].includes(variant)) {
    const points = Array.from({ length: 12 }, (_, index) => ({
      x: 24 + ((index * 71) % 270),
      y: 18 + ((index * 47) % 124),
    }));
    return (
      <svg aria-hidden="true" viewBox="0 0 320 160" preserveAspectRatio="none" style={rootStyle}>
        {variant === "signal-constellation" ? points.slice(0, 8).map((point, index) => {
          const target = points[(index + 3) % 8];
          return target ? <line key={`edge-${index}`} x1={point.x} y1={point.y} x2={target.x} y2={target.y} stroke={accent} strokeOpacity=".3" /> : null;
        }) : null}
        {points.map((point, index) => (
          <motion.circle
            key={index}
            cx={point.x}
            cy={point.y}
            r={variant === "signal-constellation" ? 2.5 : 1.8 + index % 2}
            fill={accent}
            animate={animate ? {
              cx: variant === "particle-drift"
                ? [point.x, point.x + (index % 2 ? 8 : -8), point.x]
                : [point.x, point.x + (index % 3 - 1) * 6, point.x],
              cy: [point.y, point.y + (index % 2 ? -5 : 5), point.y],
              opacity: [0.2, 0.9, 0.2],
            } : undefined}
            transition={{ duration: duration + index / 2, repeat: Infinity, delay: index * 0.13 }}
          />
        ))}
      </svg>
    );
  }

  if (["beacon-sweep", "ripple-basin", "lens-rings"].includes(variant)) {
    return (
      <svg aria-hidden="true" viewBox="0 0 320 160" preserveAspectRatio="none" style={rootStyle}>
        {variant === "beacon-sweep" ? (
          <>
            <circle cx="160" cy="80" r="4" fill={accent} />
            <circle cx="160" cy="80" r="62" fill="none" stroke={accent} strokeOpacity=".45" />
            {[0, 1].map((index) => (
              <motion.path
                key={index}
                d="M160 80 L160 18 A62 62 0 0 1 204 36 Z"
                fill={accent}
                fillOpacity={index ? ".08" : ".2"}
                style={{ transformOrigin: "160px 80px" }}
                animate={animate ? { rotate: 360 } : undefined}
                transition={{ duration: duration * (index + 1), repeat: Infinity, ease: "linear" }}
              />
            ))}
          </>
        ) : lines.slice(0, 7).map((index) => (
          <motion.circle
            key={index}
            cx={variant === "lens-rings" ? 160 + (index % 2 ? 12 : -12) : 160 + (index % 3 - 1) * 12}
            cy={80 + (index % 2 ? 5 : -5)}
            r={12 + index * 10}
            fill="none"
            stroke={accent}
            strokeWidth={variant === "lens-rings" ? 1.2 : 1}
            strokeOpacity={0.58 - index * 0.055}
            animate={animate ? {
              r: variant === "ripple-basin" ? [12 + index * 9, 18 + index * 9, 12 + index * 9] : [12 + index * 10, 15 + index * 10, 12 + index * 10],
              opacity: [0.16, 0.7, 0.16],
            } : undefined}
            transition={{ duration: duration + index * 0.42, repeat: Infinity, delay: index * 0.17 }}
          />
        ))}
      </svg>
    );
  }

  if (["crosshair-field", "raster-rain", "folded-grid", "soft-gridlight"].includes(variant)) {
    if (variant === "soft-gridlight") {
      return (
        <svg aria-hidden="true" viewBox="0 0 320 160" preserveAspectRatio="none" style={rootStyle}>
          <defs><radialGradient id={`light-${instanceId}`}><stop stopColor={accent} stopOpacity=".48" /><stop offset="1" stopColor={accent} stopOpacity="0" /></radialGradient></defs>
          <path d="M0 20H320M0 60H320M0 100H320M0 140H320M40 0V160M100 0V160M160 0V160M220 0V160M280 0V160" stroke={accent} strokeOpacity=".16" />
          <motion.circle r="72" fill={`url(#light-${instanceId})`} animate={animate ? { cx: [60, 250, 60], cy: [48, 118, 48] } : { cx: 160, cy: 80 }} transition={{ duration: duration * 2, repeat: Infinity, ease: "easeInOut" }} />
        </svg>
      );
    }
    return (
      <svg aria-hidden="true" viewBox="0 0 320 160" preserveAspectRatio="none" style={rootStyle}>
        {variant === "folded-grid" ? (
          <g fill="none" stroke={accent} strokeOpacity=".55">
            {Array.from({ length: 9 }, (_, index) => <path key={index} d={`M${index * 40} 0 L160 80 L${index * 40} 160 M${index * 40} 0 L${160 + (index - 4) * 18} 80 L${320 - index * 40} 160`} />)}
          </g>
        ) : Array.from({ length: variant === "raster-rain" ? 32 : 16 }, (_, index) => variant === "crosshair-field" ? (
          <g key={index} transform={`translate(${(index * 83) % 320} ${(index * 47) % 160})`}>
            <path d="M-4 0H4M0 -4V4" stroke={accent} strokeOpacity=".7" />
            <circle r="7" fill="none" stroke={accent} strokeOpacity=".18" />
          </g>
        ) : (
          <motion.rect
            key={index}
            x={(index * 29) % 320}
            width={index % 4 === 0 ? 2 : 1}
            height={4 + index % 7}
            fill={accent}
            animate={animate ? { y: [-10, 170], opacity: [0, 0.8, 0] } : undefined}
            transition={{ duration: duration / 2 + index * 0.08, repeat: Infinity, delay: index * 0.09, ease: "linear" }}
          />
        ))}
      </svg>
    );
  }

  return null;
}
